function correctRole(file:any,role:string){const key=file.path||file.name;setRoleOverrides(o=>({...o,[key]:role}));setDecisions(d=>{if(!(key in d))return d;const next={...d};delete next[key];return next});setValidation([]);setMoveArmed(false);if(!role)return;const tokens=file.name.replace(/\.[^.]+$/,"").split(/[\s_\-()[\]{}]+/).map((x:string)=>x.trim()).filter((x:string)=>x.length>=3&&!/^\d+$/.test(x)).slice(0,8);setFeedback(f=>({...f,[role]:[...new Set([...(f[role]||[]),...tokens])].slice(-60)}))}
