const folderMap=useMemo(()=>{if(!data)return[];return data.folders.map(f=>{const top=Object.entries(f.extensions).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([e])=>e);return {...f,role:role(f),topExtensions:top,activity:f.recentModified?Math.max(0,Math.round((Date.now()-f.recentModified)/86400000)):null}}).sort((a,b)=>b.fileCount-a.fileCount)},[data]);
