const contextDetails=useMemo(()=>{if(!data)return new Map<string,{children:{name:string;folders:number;files:number}[];keywords:string[]}>();const rootKey=data.root.replace(/[\\/]+$/,"");const detail=new Map<string,{childMap:Map<string,{name:string;folders:number;files:number}>;keywords:Map<string,number>}>();for(const f of data.folders){const rel=f.path.slice(rootKey.length).replace(/^[\\/]+/,"");const parts=rel.split(/[\\/]+/).filter(Boolean);const top=parts[0]||"(Root 직접 파일)";const d=detail.get(top)||{childMap:new Map(),keywords:new Map()};if(parts.length>1){const child=parts[1];const c=d.childMap.get(child)||{name:child,folders:0,files:0};c.folders++;c.files+=f.fileCount;d.childMap.set(child,c)}for(const k of f.keywords){const key=k.trim();if(key.length>=2)d.keywords.set(key,(d.keywords.get(key)||0)+1)}detail.set(top,d)}return new Map([...detail].map(([name,d])=>[name,{children:[...d.childMap.values()].sort((a,b)=>b.files-a.files||b.folders-a.folders).slice(0,8),keywords:[...d.keywords].sort((a,b)=>b[1]-a[1]).slice(0,6).map(([k])=>k)}]))},[data]);
const protectedPath=(path:string)=>/(z-살아가기|개인-개인|가족|아내|서현|태진|금융|세금|연말정산|의료|건강|보험|부당해고|구제신청|재심|고용노동|소송|인증서)/i.test(path);
