const contextSafety=useMemo(()=>{if(!data)return new Map<string,{protected:boolean;review:number;reviewSamples:string[]}>();const rootKey=data.root.replace(/[\\/]+$/,"");const map=new Map<string,{protected:boolean;review:number;reviewSamples:string[]}>();for(const f of data.folders){const rel=f.path.slice(rootKey.length).replace(/^[\\/]+/,"");const top=rel.split(/[\\/]+/).filter(Boolean)[0]||"(Root 직접 파일)";const x=map.get(top)||{protected:false,review:0,reviewSamples:[]};if(protectedPath(f.path))x.protected=true;if(reviewFolder(f.name)){x.review++;if(x.reviewSamples.length<4)x.reviewSamples.push(f.name)}map.set(top,x)}return map},[data]);
const folderSignature=(name:string)=>name.toLowerCase().replace(/\b(19|20)?\d{2}([._-]?\d{1,2})?\b/g,"").replace(/(관련|자료|폴더|folder|인증)/g,"").replace(/[^a-z0-9가-힣]+/g,"").trim();
